// Reviewed copy for the support center and trust pages. Keep these strings in the
// shared catalog so dynamically rendered routes use the same language as the UI.
Object.assign(window.BOZOR_COPY,{
  'Yordam':['Помощь','Help'],
  'Ishonch va qoidalar':['Доверие и правила','Trust & policies'],
  'Marketplace qoidalari':['Правила маркетплейса','Marketplace policies'],
  'Crisp Support · FAQ':['Поддержка Crisp · FAQ','Crisp Support · FAQ'],
  'To‘lov bo‘yicha yordam':['Помощь с оплатой','Payment help'],
  'Buyurtma bo‘yicha yordam':['Помощь с заказом','Order help'],
  'Qaytarim va nizolar':['Возвраты и споры','Refunds and disputes'],
  'Chatni ochish':['Открыть чат','Open chat'],
  'SentryLoot yordam markaziga xush kelibsiz.':['Добро пожаловать в центр поддержки SentryLoot.','Welcome to the SentryLoot Help Center.'],
  'Assalomu alaykum! SentryLoot yordam markaziga xush kelibsiz.':['Здравствуйте! Добро пожаловать в центр поддержки SentryLoot.','Hello! Welcome to the SentryLoot Help Center.'],
  'Quyidagi bo‘limlardan javob toping yoki Crisp chat orqali yozing. Iltimos, chatga parol, bir martalik kod, tiklash kodi, bank karta ma’lumoti yoki shaxsiy hujjat yubormang.':['Найдите ответ в разделах ниже или напишите нам в Crisp. Не отправляйте в чат пароли, одноразовые коды, коды восстановления, данные банковской карты или документы.','Find an answer below or message us through Crisp. Do not send passwords, one-time codes, recovery codes, bank card details, or identity documents in chat.'],
  'Crisp chatga yozish':['Написать в Crisp','Message us on Crisp'],
  'Hisobimga qanday kiraman yoki ro‘yxatdan o‘taman?':['Как войти или зарегистрироваться?','How do I sign in or create an account?'],
  'Bosh sahifadagi “Kirish” tugmasini bosing. Hisobingiz bo‘lmasa ro‘yxatdan o‘ting; tasdiqlash xati kelmasa spam papkasini ham tekshiring.':['Нажмите «Войти» на главной странице. Если у вас ещё нет аккаунта, зарегистрируйтесь. Если письмо для подтверждения не пришло, проверьте папку «Спам».','Select “Sign in” on the home page. If you do not have an account, register. If the verification email does not arrive, check your spam folder.'],
  'Sotuvchi yoki yordam xodimi mendan parol so‘rashi mumkinmi?':['Может ли продавец или служба поддержки запросить мой пароль?','Can a seller or support agent ask for my password?'],
  'Yo‘q. Parolingiz, OTP va tiklash kodlaringizni hech kim bilan bo‘lishmang. Faqat rasmiy sayt manzilidan foydalaning.':['Нет. Никому не сообщайте пароль, одноразовые коды и коды восстановления. Пользуйтесь только официальным адресом сайта.','No. Never share your password, one-time codes, or recovery codes. Use only the official website address.'],
  'Haqiqiy to‘lovlar ishlayaptimi?':['Реальные платежи уже работают?','Are real payments available?'],
  'Hozir ishlab chiqarish rejimida haqiqiy to‘lov va pul yechish yoqilmagan. Sinov rejimidagi to‘lovlar haqiqiy pul harakati emas. Haqiqiy to‘lovni sotuvchiga tashqaridan yubormang.':['Сейчас реальные платежи и выплаты отключены. Платежи в тестовом режиме не перемещают реальные деньги. Не переводите деньги продавцу вне платформы.','Live payments and payouts are currently disabled. Test-mode payments do not move real money. Do not pay a seller outside the platform.'],
  'Buyurtmam holatini qayerdan ko‘raman?':['Где посмотреть статус заказа?','Where can I see my order status?'],
  'Hisobingizga kirib Buyurtmalar bo‘limini oching. Yetkazish bo‘yicha savol bo‘lsa, tegishli buyurtmani tanlab ichki xabar yuboring.':['Войдите в аккаунт и откройте раздел «Заказы». Если у вас есть вопрос о доставке, выберите соответствующий заказ и отправьте сообщение через платформу.','Sign in and open Orders. If you have a delivery question, select the order and send a message through the platform.'],
  'Qanday qilib muammo haqida xabar beraman?':['Как сообщить о проблеме?','How do I report a problem?'],
  'Buyurtma ichidagi nizo/yordam amalidan foydalaning yoki Crisp chatga buyurtma raqamingizni yozing. Parol va maxfiy kodlarni yubormang.':['Используйте функцию помощи или спора в заказе либо укажите номер заказа в чате Crisp. Не отправляйте пароли и секретные коды.','Use the help or dispute action on the order, or include your order number in Crisp chat. Do not send passwords or security codes.'],
  'To‘lov bo‘yicha yordam':['Помощь с оплатой','Payment help'],
  'To‘lov tizimlari hozircha ishlab chiqarish uchun ulanmagan. Sandbox rejimida ko‘ringan “to‘lov” va qaytarimlar faqat sinov yozuvi hisoblanadi. Pul o‘tkazgan bo‘lsangiz, bank yoki to‘lov provayderingizga murojaat qiling va bizga buyurtma raqami hamda maxfiy bo‘lmagan ma’lumotlarni yozing.':['Платёжные системы пока не подключены для реальных операций. «Платежи» и возвраты в тестовом режиме являются только тестовыми записями. Если вы отправили деньги, обратитесь в свой банк или платёжную систему и сообщите нам номер заказа и сведения, не содержащие секретных данных.','Payment systems are not enabled for live transactions yet. “Payments” and refunds shown in sandbox are test records only. If you sent money, contact your bank or payment provider and send us the order number and non-sensitive details.'],
  'To‘lov haqida yozish':['Написать об оплате','Ask about a payment'],
  'Buyurtma holati va sotuvchi yuborgan yetkazish ma’lumoti hisobingizdagi Buyurtmalar bo‘limida ko‘rinadi. Yetkazish ko‘rinmasa yoki buyurtmada xato bo‘lsa, buyurtma raqamingizni ko‘rsatib chatga yozing. Login ma’lumotlarini chatga yubormang.':['Статус заказа и данные о доставке от продавца отображаются в разделе «Заказы». Если сведения о доставке не появились или в заказе есть ошибка, напишите нам в чат и укажите номер заказа. Не отправляйте данные для входа.','Order status and seller delivery details appear in Orders. If delivery details are missing or something is wrong with the order, message us with the order number. Do not send login credentials in chat.'],
  'Buyurtma haqida yozish':['Написать о заказе','Ask about an order'],
  'Qaytarim va nizolar bo‘yicha yordam':['Помощь с возвратом и спором','Refund and dispute help'],
  'Muammoni imkon qadar tez, buyurtma sahifasidagi nizo/yordam amali orqali bildiring. Moderator qo‘shimcha ma’lumot so‘rashi mumkin. Sandbox qaytarimi haqiqiy pulni qaytarmaydi; real savdolar hali yoqilmagan. Amaldagi mahalliy qonunlar bo‘yicha huquqlaringiz saqlanadi. Batafsil:':['Как можно скорее сообщите о проблеме через функцию помощи или спора на странице заказа. Модератор может запросить дополнительные сведения. Тестовый возврат не возвращает реальные деньги; реальные продажи ещё не включены. Ваши права по действующему местному законодательству сохраняются. Подробнее:','Report the issue as soon as possible using the help or dispute action on the order page. A moderator may request more information. Sandbox refunds do not return real money; live sales are not enabled yet. Your rights under applicable local law remain unaffected. More details:'],
  'Nizo haqida yozish':['Написать о споре','Ask about a dispute'],
  'Chat xabarlari javob berish va muammoni ko‘rib chiqish uchun Crisp orqali qayta ishlanadi.':['Сообщения чата обрабатываются через Crisp, чтобы мы могли ответить и рассмотреть ваш вопрос.','Chat messages are processed through Crisp so we can respond and review your request.'],
  'Crisp maxfiylik siyosati':['Политика конфиденциальности Crisp','Crisp Privacy Policy'],
  'Maxfiylik yoki hisob bo‘yicha:':['По вопросам конфиденциальности или аккаунта:','For privacy or account questions:'],
  'Amal qilish sanasi: 9-oktabr 2026.':['Дата вступления в силу: 9 октября 2026 г.','Effective date: October 9, 2026.'],
  'Ushbu sahifa SentryLoot marketplace’dan foydalanish qoidalarini tushuntiradi. Operator: Asliddinov Shukhratjon.':['На этой странице описаны правила использования маркетплейса SentryLoot. Оператор: Asliddinov Shukhratjon.','This page explains the rules for using the SentryLoot marketplace. Operator: Asliddinov Shukhratjon.'],
  'Xizmat va hisob':['Сервис и аккаунт','Service and account'],
  'Hisob ma’lumotlarini to‘g‘ri saqlang, hisobingiz xavfsizligi uchun javobgarsiz va kirish kodlarini boshqalarga bermang. Saytdan faqat qonuniy maqsadda va ushbu qoidalarga muvofiq foydalaning.':['Храните данные аккаунта в безопасности. Вы отвечаете за безопасность своего аккаунта и не должны передавать другим коды доступа. Пользуйтесь сайтом только законно и в соответствии с этими правилами.','Keep your account details secure. You are responsible for your account security and must not share access codes. Use the site only for lawful purposes and in line with these terms.'],
  'E’lonlar va xaridlar':['Объявления и покупки','Listings and purchases'],
  'E’lonlar faqat ko‘rib chiqilgan o‘yinlar va ruxsat etilgan mahsulotlar bo‘yicha joylashtirilishi mumkin. O‘yin noshirining qoidalari har doim amal qiladi; platformadagi e’lon yoki tekshiruv noshir ruxsatini anglatmaydi. Tovar va xizmat tavsifini xariddan avval tekshiring.':['Объявления разрешены только для проверенных игр и допустимых товаров. Правила издателя игры продолжают действовать; объявление или проверка на платформе не означает одобрение издателя. До покупки ознакомьтесь с описанием товара или услуги.','Listings are limited to reviewed games and permitted products. Game publisher rules still apply; a listing or marketplace review does not mean the publisher permits it. Review the item or service details before buying.'],
  'To‘lov va platforma holati':['Платежи и статус платформы','Payments and service status'],
  'Hozir haqiqiy to‘lov, qaytarim va sotuvchi payout tizimlari yoqilmagan. Sandbox amallari pul qabul qilmaydi, o‘tkazmaydi yoki qaytarmaydi. Sayt funksiyalari sinov yoki texnik xizmat sabab o‘zgarishi mumkin.':['Сейчас реальные платежи, возвраты и выплаты продавцам отключены. Тестовый режим не принимает, не переводит и не возвращает деньги. Функции сайта могут меняться во время тестирования или обслуживания.','Live payments, refunds, and seller payouts are currently disabled. Sandbox actions do not accept, transfer, or return money. Site features may change during testing or maintenance.'],
  'Qoidabuzarlik va aloqa':['Нарушения и связь','Violations and contact'],
  'Qoidalarni buzgan e’lon yoki hisob cheklanishi mumkin. Majburiy mahalliy iste’molchi huquqlari ushbu matn bilan bekor qilinmaydi. Savollar:':['За нарушение правил объявление или аккаунт могут быть ограничены. Этот текст не отменяет обязательные права потребителей по местному законодательству. Вопросы:','Listings or accounts that violate these rules may be restricted. These terms do not remove mandatory consumer rights under local law. Questions:'],
  'Hozir haqiqiy to‘lovlar yoqilmagan. Sandbox qaytarimi yozuvi haqiqiy pul qaytarilishi emas.':['Реальные платежи пока отключены. Запись о тестовом возврате не означает возврат реальных денег.','Live payments are not enabled. A sandbox refund record is not a real-money refund.'],
  'Muammo haqida xabar berish':['Сообщить о проблеме','Report a problem'],
  'Buyurtmada yetkazish, tavsif yoki ruxsatsiz to‘lov bilan bog‘liq muammo bo‘lsa, buyurtma sahifasidagi nizo/yordam amalidan imkon qadar tez xabar bering. Buyurtma raqami va maxfiy bo‘lmagan dalillarni kiriting. Moderator buyurtma yozuvlarini ko‘rib, zarur bo‘lsa qo‘shimcha ma’lumot so‘raydi.':['Если возникла проблема с доставкой, описанием или несанкционированным платежом, как можно скорее сообщите об этом через функцию спора или помощи на странице заказа. Укажите номер заказа и приложите материалы без секретных данных. Модератор проверит заказ и при необходимости запросит дополнительную информацию.','If there is a problem with delivery, the listing description, or an unauthorized payment, report it as soon as possible using the help or dispute action on the order page. Include the order number and non-sensitive evidence. A moderator will review the order and may request more information.'],
  'Qaror va qaytarim':['Решение и возврат','Review and refund'],
  'Hozir moderator panelidagi qaytarim funksiyasi faqat sandbox qaydini yaratadi va real pul ko‘chirmaydi. Haqiqiy savdo ochilishidan oldin to‘lov provayderi va qonuniy talablarni hisobga olgan aniq qaytarim tartibi e’lon qilinadi. Bu siyosat iste’molchining qonun bo‘yicha majburiy huquqlarini cheklamaydi.':['Сейчас функция возврата в панели модератора создаёт только тестовую запись и не переводит реальные деньги. До запуска реальных продаж будет опубликован порядок возврата с учётом требований платёжного провайдера и законодательства. Эта политика не ограничивает обязательные права потребителей.','The moderator refund action currently creates a sandbox record only and does not transfer real money. Before live sales begin, we will publish a refund process that accounts for payment-provider and legal requirements. This policy does not limit mandatory consumer rights.'],
  'Yordam uchun':['За помощью обратитесь:','For help, contact'],
  'Sotuvchining majburiyatlari':['Обязанности продавца','Seller responsibilities'],
  'Faqat o‘zingizga tegishli yoki sotishga vakolatingiz bor mahsulotni joylang; o‘yin noshiri transferga ruxsat berishi shart.':['Размещайте только товары, которыми владеете или которые уполномочены продавать; издатель игры должен разрешать передачу.','List only products you own or are authorized to sell; the game publisher must permit the transfer.'],
  'Tavsif, narx, mavjudlik va yetkazish shartlarini aniq ko‘rsating.':['Чётко указывайте описание, цену, наличие и условия доставки.','Describe the item, price, availability, and delivery terms accurately.'],
  'Xaridor bilan platforma ichida muomala qiling; platformadan tashqari to‘lov so‘ramang.':['Общайтесь с покупателем на платформе и не просите оплату вне неё.','Communicate with buyers on the platform and do not request off-platform payments.'],
  'Parol, OTP, tiklash kodi yoki boshqa maxfiy ma’lumotlarni ochiq e’londa yoki chatda so‘ramang.':['Не запрашивайте пароли, одноразовые коды, коды восстановления и другие секретные данные в объявлениях или чате.','Never ask for passwords, one-time codes, recovery codes, or other secrets in listings or chat.'],
  'Shaxsni tasdiqlashda faqat rasmiy xavfsiz oqimdan foydalaning.':['Для подтверждения личности используйте только официальный защищённый процесс.','Use only the official secure process for identity verification.'],
  'Hisoblar va to‘lovlar':['Аккаунты и платежи','Accounts and payments'],
  'O‘yin akkauntlari faqat noshir aniq ruxsat bergan hollarda ro‘yxatga olinishi mumkin. Hozir ishlab chiqarish savdosi va sotuvchi payout yoqilmagan; sandbox yozuvlari real pul emas.':['Игровые аккаунты можно размещать только при прямом разрешении издателя. Реальные продажи и выплаты продавцам сейчас отключены; записи sandbox не являются реальными деньгами.','Game accounts may be listed only when the publisher explicitly permits the transfer. Live sales and seller payouts are currently disabled; sandbox records are not real money.'],
  'Qoidabuzarliklar':['Нарушения','Violations'],
  'Soxta e’lon, o‘g‘irlangan yoki buzilgan hisob, tashqi to‘lovga undash yoxud xaridorni chalg‘itish moderatsiya va hisob cheklovlariga olib kelishi mumkin.':['Поддельные объявления, украденные или взломанные аккаунты, просьбы об оплате вне платформы и введение покупателя в заблуждение могут привести к модерации и ограничениям аккаунта.','Fake listings, stolen or compromised accounts, off-platform payment requests, or misleading buyers may lead to moderation and account restrictions.'],
  'Quyidagilarni joylash, taklif qilish yoki sotishga yordam berish taqiqlanadi:':['Запрещено размещать, предлагать или содействовать продаже следующего:','The following may not be listed, offered, or promoted for sale:'],
  'O‘g‘irlangan, buzib kirilgan, ijaraga olingan yoki egaligi tasdiqlanmagan akkauntlar va raqamli mahsulotlar.':['Украденные, взломанные, арендованные аккаунты и цифровые товары, право собственности на которые не подтверждено.','Stolen, compromised, rented, or unverified game accounts and digital products.'],
  'Noshir shartlari transferni taqiqlagan o‘yin akkauntlari, jumladan loyiha qoidalarida cheklangan EA/FC Mobile, PUBG Mobile, Steam va Riot akkaunt transferlari.':['Игровые аккаунты, передачу которых запрещают условия издателя, включая указанные в правилах проекта ограничения для аккаунтов EA/FC Mobile, PUBG Mobile, Steam и Riot.','Game accounts whose transfer is prohibited by publisher terms, including EA/FC Mobile, PUBG Mobile, Steam, and Riot account transfers restricted by this project’s rules.'],
  'Cheat, bot, exploit, zararli dastur, o‘g‘irlangan to‘lov vositasi yoki firibgarlik xizmatlari.':['Читы, боты, эксплойты, вредоносные программы, украденные платёжные средства и услуги для мошенничества.','Cheats, bots, exploits, malware, stolen payment methods, or fraud services.'],
  'Soxta valyuta, soxta kvitansiya yoki ruxsatsiz xarid/chargeback takliflari.':['Поддельная валюта, фальшивые квитанции или предложения несанкционированных покупок и чарджбэков.','Fake currency, forged receipts, or unauthorized purchase/chargeback offers.'],
  'Boshqalarning shaxsiy ma’lumotlari yoki platformadan tashqari to‘lov talablari.':['Чужие персональные данные или требования оплатить вне платформы.','Other people’s personal information or requests for off-platform payment.'],
  'Gumonli e’lon haqida':['Сообщите о подозрительном объявлении через','Report a suspicious listing to the'],
  'yordam markaziga':['центр поддержки','Help Center'],
  'Savdo, xavfsizlik, shaxsiy ma’lumotlar yoki shikoyatlar bo‘yicha biz bilan bog‘laning:':['По вопросам торговли, безопасности, персональных данных или жалоб свяжитесь с нами:','Contact us about marketplace use, safety, personal data, or complaints:'],
  'Chatini ochish':['Открыть чат','Open chat'],
  'Xabarda buyurtma raqamini ko‘rsatishingiz mumkin. Parol, bir martalik kod, to‘lov karta raqami yoki tiklash kodini yubormang.':['В сообщении можно указать номер заказа. Не отправляйте пароль, одноразовый код, номер банковской карты или код восстановления.','You may include an order number. Do not send passwords, one-time codes, payment card numbers, or recovery codes.'],
  'Bu sahifa amaldagi xizmat holatini tushuntiradi, lekin yuridik maslahat emas. Haqiqiy to‘lov va savdo hali ishga tushmagan.':['Эта страница описывает текущее состояние сервиса и не является юридической консультацией. Реальные платежи и продажи ещё не запущены.','This page describes the current service and is not legal advice. Live payments and sales have not launched.'],
  'SentryLoot uchun muhim ma’lumot va qoidalar.':['Важная информация и правила SentryLoot.','Important SentryLoot information and rules.'],
  'Barcha marketplace qoidalari':['Все правила маркетплейса','All marketplace policies'],
  'Yordam markazi':['Центр поддержки','Help Center'],
  'Sahifa':['Страница','Page']
});

